#include <string.h>
#include <errno.h>
#include <sys/file.h>
#include <ratelprof.h>
#include <ratelprof_ext.h>

#include "rprofrep_encode.h"

typedef struct ratelprof_plugin_s {
    api_callback_handler_t callback[RATELPROF_NB_DOMAIN_EXT];

    activity_callback_t activity_callback;
    rprofrep_encode_context_t* ctx;
} ratelprof_plugin_t;


void on_enter_api_callback(ratelprof_domain_t domain, ratelprof_api_id_t id, void* user_activity)
{
    ratelprof_api_activity_t* activity = (ratelprof_api_activity_t*)user_activity;
    get_id(&activity->id);
    activity->domain = domain;
    activity->funid = id;
    activity->pid = get_pid();
    activity->tid = get_tid();
}

void on_exit_api_callback(ratelprof_domain_t domain, ratelprof_api_id_t id, void* user_activity)
{
    ratelprof_api_activity_t* activity = (ratelprof_api_activity_t*)user_activity;
	(void)domain;
	(void)id;
    get_correlation_id(&activity->corr_id, &activity->has_children);
    ratelprof_activity_pool_push_activity(activity);
}


ratelprof_status_t activity_callback(ratelprof_domain_t domain, const void* activity, void* user_args)
{
    if (domain < 0 || (int)domain >= RATELPROF_NB_DOMAIN_EXT) {
        LOG(LOG_LEVEL_FATAL, "Unknown domain : %d\n", domain);
        exit(1);
    }
    rprofrep_encode_activity_to_buffer((rprofrep_encode_context_t*)user_args, domain, activity);
    return 0;
}


static inline const char* get_context_id() {
    uint32_t pid = get_pid();
    uint64_t time = ratelprof_get_experiment_start_epoch();
    static char context_id[64];
    snprintf(context_id, sizeof(context_id), "pid_%u_time_%lu", pid, time);
    return context_id;
}


static inline char* get_report_filename() {
    static char filename[512];
    int rank = get_mpi_rank_from_env();  // returns -1 if not in MPI

    const char* base_filename = get_output_file();
    if (rank >= 0) {
        snprintf(filename, sizeof(filename), "rank_%d_%s", rank, base_filename);
    } else {
        snprintf(filename, sizeof(filename), "%s", base_filename);
    }
    return filename;
}


